(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0RC_1LC1LD_0RD0LC_1RA1RD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_000_001_00 q0 ++ [S1;S0]) [] j A0_1RB0RC_1LC1LD_0RD0LC_1RA1RD.
Proof.
  intros p j q0 E. destruct (Alph_000_001_00.cview_some_Alph_000_001_00 p j q0 E) as (H1 & _).
  unfold Cc_1RB0RC_1LC1LD_0RD0LC_1RA1RD, cden, A0_1RB0RC_1LC1LD_0RD0LC_1RA1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S0;S0;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB0RC_1LC1LD_0RD0LC_1RA1RD : forall p j q0, cview p = (j, Some q0) ->
  cden (Ap_Alph_000_001_00 q0 ++ [S1;S0]) [] j A1_1RB0RC_1LC1LD_0RD0LC_1RA1RD = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_000_001_00.cview_some_Alph_000_001_00 p j q0 E) as (_ & H2).
  unfold Cc_1RB0RC_1LC1LD_0RD0LC_1RA1RD, cden, A1_1RB0RC_1LC1LD_0RD0LC_1RA1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S0;S0;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0RC_1LC1LD_0RD0LC_1RA1RD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (8 * j + 6). split; [lia|].
  rewrite (gsi_1RB0RC_1LC1LD_0RD0LC_1RA1RD p j q0 E).
  rewrite (srun_sound tm false true chi_1RB0RC_1LC1LD_0RD0LC_1RA1RD A0_1RB0RC_1LC1LD_0RD0LC_1RA1RD A1_1RB0RC_1LC1LD_0RD0LC_1RA1RD 8 6
             run_int_1RB0RC_1LC1LD_0RD0LC_1RA1RD (Ap_Alph_000_001_00 q0 ++ [S1;S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB0RC_1LC1LD_0RD0LC_1RA1RD p j q0 E).
Qed.

Lemma gso_1RB0RC_1LC1LD_0RD0LC_1RA1RD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0RC_1LC1LD_0RD0LC_1RA1RD.
Proof.
  intros p j E. destruct (Alph_000_001_00.cview_none_Alph_000_001_00 p j E) as (H1 & _).
  unfold Cc_1RB0RC_1LC1LD_0RD0LC_1RA1RD, cden, B0_1RB0RC_1LC1LD_0RD0LC_1RA1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0RC_1LC1LD_0RD0LC_1RA1RD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0RC_1LC1LD_0RD0LC_1RA1RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RC_1LC1LD_0RD0LC_1RA1RD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_000_001_00.cview_none_Alph_000_001_00 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0RC_1LC1LD_0RD0LC_1RA1RD
             = (StC, (rep [S0;S0;S0] (S j) ++ [S0;S0;S1], S0, [S0;S1]))).
  { unfold cden, B1_1RB0RC_1LC1LD_0RD0LC_1RA1RD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S0;S0;S0] (S j) ++ [S0;S0;S1]) ++ [S0], S0, [S0;S1]))).
  { unfold Cc_1RB0RC_1LC1LD_0RD0LC_1RA1RD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB0RC_1LC1LD_0RD0LC_1RA1RD. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB0RC_1LC1LD_0RD0LC_1RA1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RC_1LC1LD_0RD0LC_1RA1RD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RC_1LC1LD_0RD0LC_1RA1RD B0_1RB0RC_1LC1LD_0RD0LC_1RA1RD B1_1RB0RC_1LC1LD_0RD0LC_1RA1RD 8 14 p j' [] []).
    + exact run_ovf_1RB0RC_1LC1LD_0RD0LC_1RA1RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RC_1LC1LD_0RD0LC_1RA1RD p j' E).
    + exact (geo_1RB0RC_1LC1LD_0RD0LC_1RA1RD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB0RC_1LC1LD_0RD0LC_1RA1RD : stepn tmm_1RB0RC_1LC1LD_0RD0LC_1RA1RD 12 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB0RC_1LC1LD_0RD0LC_1RA1RD 12 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB0RC_1LC1LD_0RD0LC_1RA1RD 12 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB0RC_1LC1LD_0RD0LC_1RA1RD : existsb (fun tg => cfires tmm_1RB0RC_1LC1LD_0RD0LC_1RA1RD c0 12 tg) pins_1RB0RC_1LC1LD_0RD0LC_1RA1RD = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RC_1LC1LD_0RD0LC_1RA1RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RC_1LC1LD_0RD0LC_1RA1RD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RC_1LC1LD_0RD0LC_1RA1RD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RC_1LC1LD_0RD0LC_1RA1RD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RC_1LC1LD_0RD0LC_1RA1RD : forall t, ~ In t pins_1RB0RC_1LC1LD_0RD0LC_1RA1RD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0RC_1LC1LD_0RD0LC_1RA1RD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0RC_1LC1LD_0RD0LC_1RA1RD
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0RC_1LC1LD_0RD0LC_1RA1RD
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 5; SWinL 2]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0RC_1LC1LD_0RD0LC_1RA1RD
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0RC_1LC1LD_0RD0LC_1RA1RD
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RC_1LC1LD_0RD0LC_1RA1RD
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 5; SWinL 3]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0RC_1LC1LD_0RD0LC_1RA1RD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0RC_1LC1LD_0RD0LC_1RA1RD
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 3]).
    vm_compute; reflexivity.
Qed.

Theorem qhtrm_1RB0RC_1LC1LD_0RD0LC_1RA1RD : NonHalt tmm_1RB0RC_1LC1LD_0RD0LC_1RA1RD /\ QHBoundTr 32779478 tmm_1RB0RC_1LC1LD_0RD0LC_1RA1RD /\ QuasiHaltsTr tmm_1RB0RC_1LC1LD_0RD0LC_1RA1RD.
Proof.
  apply (lap_qh_stage tmm_1RB0RC_1LC1LD_0RD0LC_1RA1RD pins_1RB0RC_1LC1LD_0RD0LC_1RA1RD Cc 1 12 32779478).
  - exact bootq_1RB0RC_1LC1LD_0RD0LC_1RA1RD.
  - intros p _. apply lap_1RB0RC_1LC1LD_0RD0LC_1RA1RD.
  - intros t Ht p _. apply fire_1RB0RC_1LC1LD_0RD0LC_1RA1RD. exact Ht.
  - exact wit_1RB0RC_1LC1LD_0RD0LC_1RA1RD.
  - vm_cast_no_check (eq_refl true).
Qed.

Theorem qhtr_1RB0RC_1LC1LD_0RD0LC_1RA1RD : NonHalt tm_1RB0RC_1LC1LD_0RD0LC_1RA1RD /\ QHBoundTr 32779478 tm_1RB0RC_1LC1LD_0RD0LC_1RA1RD /\ QuasiHaltsTr tm_1RB0RC_1LC1LD_0RD0LC_1RA1RD.
Proof. apply (qh_triple_unmirror 32779478 tm_1RB0RC_1LC1LD_0RD0LC_1RA1RD). rewrite mirror_ok_1RB0RC_1LC1LD_0RD0LC_1RA1RD. exact qhtrm_1RB0RC_1LC1LD_0RD0LC_1RA1RD. Qed.

