Lemma fire_1RB0RD_0LC0RB_1LD0LD_1LA1LC : forall t, ~ In t pins_1RB0RD_0LC0RB_1LD0LD_1LA1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
